defmodule DebtReliefTracker.Engine.ParityTest do
  # The integer-cents engine must reproduce the Decimal engine's results
  # (fixtures generated by test/support/fixtures/generate_engine_scenarios.exs).
  # Orders, minimums and month counts match exactly; interest totals may drift
  # by under a cent per debt-month because the integer engine rounds interest
  # to a cent when it is posted.
  use ExUnit.Case, async: true

  alias DebtReliefTracker.Engine.Convert
  alias DebtReliefTracker.Engine.Planning

  @fixture Path.expand("../../support/fixtures/engine_scenarios.json", __DIR__)
  @scenarios @fixture |> File.read!() |> Jason.decode!() |> Map.fetch!("scenarios")

  @atoms %{
    "revolving" => :revolving,
    "installment" => :installment,
    "active" => :active,
    "paid_off" => :paid_off,
    "cash_flow" => :cash_flow,
    "snowball" => :snowball,
    "avalanche" => :avalanche,
    "insufficient_budget" => :insufficient_budget,
    "did_not_converge" => :did_not_converge
  }

  defp atom(name), do: Map.fetch!(@atoms, name)

  for scenario <- @scenarios do
    describe "scenario #{scenario["name"]}" do
      @scenario scenario

      setup do
        debts =
          Enum.map(@scenario["debts"], fn row ->
            Convert.debt(%{
              id: row["id"],
              type: atom(row["type"]),
              status: atom(row["status"]),
              exclude_from_plan: row["exclude_from_plan"],
              balance: row["balance"],
              apr: row["apr"],
              fixed_payment: row["fixed_payment"],
              minimum_payment_floor: row["minimum_payment_floor"],
              minimum_payment_rate: row["minimum_payment_rate"],
              credit_limit: row["credit_limit"]
            })
          end)

        %{
          debts: debts,
          budget: Convert.to_cents(@scenario["budget"]),
          lump: Convert.to_cents(@scenario["lump_sum"]),
          expected: @scenario["expected"]
        }
      end

      test "minimum payments match to the cent", %{debts: debts, expected: expected} do
        for debt <- debts do
          assert Planning.eligible([debt]) == [] or
                   Planning.total_minimum_payments([debt]) ==
                     Convert.to_cents(expected["minimum_payments"][debt.id])
        end

        assert Planning.total_minimum_payments(debts) ==
                 Convert.to_cents(expected["total_minimum_payments"])
      end

      test "strategy order, outcome and first month match", ctx do
        for {name, exp} <- ctx.expected["strategies"] do
          strategy = atom(name)

          assert ctx.debts
                 |> Planning.eligible()
                 |> then(&Planning.order(strategy, &1))
                 |> Enum.map(& &1.id) ==
                   exp["order"]

          result = Planning.simulate(ctx.debts, ctx.budget, strategy)

          case exp["simulation"] do
            %{"status" => "error", "reason" => reason} ->
              assert result == {:error, atom(reason)}

            %{"status" => "ok"} = sim ->
              assert {:ok, %{total_months: months, total_interest: interest, months: [first | _]}} =
                       result

              assert months == sim["total_months"]

              tolerance = months * length(ctx.debts)
              assert abs(interest - Convert.to_cents(sim["total_interest"])) <= tolerance

              assert first.target_debt_id == sim["first_month"]["target_debt_id"]
          end
        end
      end

      test "windfall saves the same months and about the same interest", ctx do
        for {name, exp} <- ctx.expected["strategies"], exp["windfall"]["months_saved"] do
          strategy = atom(name)

          assert {:ok, %{months_saved: saved, interest_saved: interest_saved}} =
                   Planning.windfall_cascade(ctx.debts, ctx.budget, strategy, ctx.lump)

          assert saved == exp["windfall"]["months_saved"]

          assert abs(interest_saved - Convert.to_cents(exp["windfall"]["interest_saved"])) <=
                   length(ctx.debts) * 100
        end
      end
    end
  end
end
